type Store struct {
	mu sync.RWMutex
	m  map[string]string
}

func NewStore() *Store { return &Store{m: map[string]string{}} }

func (s *Store) Add(url string) string {
	b := make([]byte, 4)
	rand.Read(b)
	code := hex.EncodeToString(b)
	s.mu.Lock()
	s.m[code] = url
	s.mu.Unlock()
	return code
}

func (s *Store) Get(code string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.m[code]
	return u, ok
}

func main() {}

func (s *Store) shorten(w http.ResponseWriter, r *http.Request) {
	url := r.FormValue("url")
	if url == "" {
		http.Error(w, "missing url", http.StatusBadRequest)
		return
	}
	fmt.Fprintln(w, s.Add(url))
}

func (s *Store) redirect(w http.ResponseWriter, r *http.Request) {
	if u, ok := s.Get(r.PathValue("code")); ok {
		http.Redirect(w, r, u, http.StatusFound)
		return
	}
	http.NotFound(w, r)
}

func TestStore(t *testing.T) {
	s := NewStore()
	code := s.Add("https://example.com")
	got, ok := s.Get(code)
	if !ok || got != "https://example.com" {
		t.Fatalf("unexpected: %v %v", got, ok)
	}
}

